export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let pending = [];

  try {
    const stored = storage.getItem(key);
    if (stored !== null) {
      const parsed = JSON.parse(stored);
      if (Array.isArray(parsed)) {
        pending = parsed;
      }
    }
  } catch {
    // Invalid persisted data is treated as an empty queue.
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(pending));
  }

  function enqueue(action) {
    if (pending.some((item) => item.id === action.id)) {
      return;
    }

    if (action.dedupeKey !== undefined) {
      const match = pending.find(
        (item) =>
          item !== inFlight && item.dedupeKey === action.dedupeKey,
      );

      if (match) {
        match.type = action.type;
        match.payload = action.payload;
        match.attempts = 0;
        persist();
        return;
      }
    }

    pending.push({
      id: action.id,
      type: action.type,
      payload: action.payload,
      dedupeKey: action.dedupeKey,
      attempts: 0,
    });
    persist();
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveFlush;
    let rejectFlush;
    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    // Publish the promise before send can run or re-enter flush.
    runningFlush = promise;

    void (async () => {
      const sent = [];
      const failed = [];

      try {
        while (pending.length > 0) {
          const item = pending[0];
          inFlight = item;

          let outcome = "retryable";

          try {
            const response = await send({
              id: item.id,
              type: item.type,
              payload: item.payload,
            });
            const ok = response == null ? undefined : response.ok;

            if (ok === true) {
              outcome = "sent";
            } else if (ok === false && response.retryable === false) {
              outcome = "rejected";
            }
          } catch {
            // Rejections and synchronous throws are retryable failures.
          }

          if (outcome === "sent" || outcome === "rejected") {
            pending.shift();
            persist();

            if (outcome === "sent") {
              sent.push(item.id);
            } else {
              failed.push({ id: item.id, reason: "rejected" });
            }

            inFlight = null;
            continue;
          }

          item.attempts += 1;
          persist();

          if (item.attempts >= maxAttempts) {
            pending.shift();
            persist();
            failed.push({ id: item.id, reason: "max-attempts" });
          }

          // Every retryable failure stops this run, even if removed.
          break;
        }

        resolveFlush({ sent, failed, remaining: pending.length });
      } catch (error) {
        rejectFlush(error);
      } finally {
        inFlight = null;
        runningFlush = null;
      }
    })();

    return promise;
  }

  function size() {
    return pending.length;
  }

  function peek() {
    return pending.map(({ id, type, payload, dedupeKey, attempts }) => ({
      id,
      type,
      payload,
      dedupeKey,
      attempts,
    }));
  }

  return { enqueue, flush, size, peek };
}
